import com.evolveum.midpoint.prism.path.ItemPath
import com.evolveum.midpoint.schema.constants.SchemaConstants
import com.evolveum.midpoint.util.QNameUtil
import com.evolveum.midpoint.xml.ns._public.common.common_3.FocusType

def delta = midpoint.focusContext?.primaryDelta
def assignmentDelta = delta?.findContainerDelta(ItemPath.create(FocusType.F_ASSIGNMENT))
def addedAssignments = delta?.isAdd() ? [] : (assignmentDelta?.valuesToAdd ?: [])
return addedAssignments.any { a ->
    def assignment = a.asContainerable()
    assignment.targetRef != null
            && QNameUtil.match(assignment.targetRef.relation, SchemaConstants.ORG_DEPUTY)
            && assignment.activation?.validTo == null
}
